def write_files():
    for name, content in FILES.items():
        path=Path(name); path.parent.mkdir(parents=True, exist_ok=True); path.write_text(content, encoding="utf-8")
def main():
    p=argparse.ArgumentParser(description="Bootstrap Freehold v11f with CLI Toolchain")
    p.add_argument("--run", action="store_true"); p.add_argument("--smoke", action="store_true"); p.add_argument("--generate-ebnf", action="store_true"); p.add_argument("--log", default=None); p.add_argument("--json-summary", default=None)
    args=p.parse_args(); write_files(); print("[OK] Freehold CLI project files written.")
    if args.generate_ebnf: subprocess.run([sys.executable,"-m","freehold","ebnf"], check=True)
    if args.smoke:
        subprocess.run([sys.executable,"-m","freehold","--version"], check=True)
        subprocess.run([sys.executable,"-m","freehold","verify","examples/hello_cli.fh"], check=True)
        subprocess.run([sys.executable,"-m","freehold","run","examples/hello_cli.fh"], check=True)
    if args.run:
        cmd=[sys.executable,"-m","freehold","test"]
        if args.log: cmd += ["--log",args.log]
        if args.json_summary: cmd += ["--json-summary",args.json_summary]
        raise SystemExit(subprocess.run(cmd,text=True).returncode)
if __name__=="__main__": main()
